class Solution
{
public:
    vector<int> getModifiedArray(int length, vector<vector<int>>& updates) {
        vector<int> result(length, 0);
        for (const auto& u : updates) {
            result[u[0]] += u[2];
            if (u[1] + 1 < length) result[u[1] + 1] -= u[2];
        }
        for (int i = 1; i < length; ++i)
        {
            result[i] += result[i - 1];
        }
        return result;
    }
};
